<div class="page-shell dark-section"><article class="page-hero wrap"><span class="eyebrow"><?=e($discussion['category'])?></span><h1><?=e($discussion['title'])?></h1><p><?=nl2br(e($discussion['body']))?></p><small>Started by <?=e($discussion['full_name'])?></small></article><section class="wrap two-column"><div><h2>Replies</h2><?php foreach($comments as $c):?><article class="comment"><strong><?=e($c['full_name'])?></strong><p><?=nl2br(e($c['body']))?></p></article><?php endforeach;?></div><div><?php if($discussion['status']==='locked'):?><p>This discussion is locked.</p><?php elseif(auth()):?><form class="form-card" method="post" action="<?=url('discussions/'.$discussion['id'].'/comments')?>"><?=csrf_field()?><div class="field"><label for="body">Add a constructive reply</label><textarea id="body" name="body" required></textarea></div><button class="pill pill-light">Post reply</button></form><?php else:?><a class="pill pill-light" href="<?=url('login')?>">Sign in to reply</a><?php endif;?></div></section></div>
